<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><h1>Admission Details</h1><p>Bounded persisted admission report.</p></div><button class="btn btn--primary" onclick="window.print()">Print</button></header><form class="filter-bar filter-bar--compact"><input class="module-input" name="search" value="<?= e($search) ?>" placeholder="Name or registration"><select class="module-select" name="class"><option value="">All Classes</option><?php foreach($classes as$c):?><option value="<?= $c['id'] ?>" <?= $selectedClass==$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach ?></select><button class="btn btn--secondary">Filter</button></form><section class="module-card"><div class="module-card__body"><div class="table-scroll wide-report"><table class="data-table"><thead><tr><th>Sr</th><th>ID</th><th>Student Name</th><th>Father Name</th><th>Class</th><th>Discount</th><th>Admission Date</th><th>DOB</th><th>Age</th><th>Gender</th><th>NIC</th><th>Religion</th><th>Cast</th><th>Status</th></tr></thead><tbody><?php foreach($rows as$i=>$s):$age=$s['date_of_birth']?(new DateTimeImmutable($s['date_of_birth']))->diff(new DateTimeImmutable('today'))->y:null;?><tr><td><?= $paginator->offset()+$i+1 ?></td><td><?= e($s['registration_no']) ?></td><td><?= e($s['student_name']) ?></td><td><?= e($s['father_name']?:'—') ?></td><td><?= e($s['class_name']) ?></td><td><?= e($s['discount_in_fee']) ?>%</td><td><?= e($s['date_of_admission']) ?></td><td><?= e($s['date_of_birth']?:'—') ?></td><td><?= $age??'—' ?></td><td><?= e($s['gender']?:'—') ?></td><td><?= e($s['birth_form_nic']?:'—') ?></td><td><?= e($s['religion']?:'—') ?></td><td><?= e($s['caste']?:'—') ?></td><td><?= e($s['status']) ?></td></tr><?php endforeach ?></tbody></table></div><p><?= $paginator->total ?> records · Page <?= $paginator->currentPage ?> / <?= $paginator->lastPage() ?></p></div></section></div></div></main>
